    h,w=len(g),len(g[0]); bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and (i,j) not in seen:
                c=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for di,dj in((-1,0),(1,0),(0,-1),(0,1)):
                        p,q2=a+di,b+dj
                        if 0<=p<h and 0<=q2<w and g[p][q2]==c and (p,q2) not in seen:
                            seen.add((p,q2)); q.append((p,q2))
                out.append((c,cells))
    return out
