            R_V={(2*mr-a,b) for a,b in S}; off_v=(mr-R_V[kn][0], mc-R_V[kn][1])
            stV=frozenset((p+off_v) for p in R_V)
            R_H={(a,2*mc-b) for a,b in S}; off_h=(mr-R_H[kn][0], mc-R_H[kn][1])
