            # fallback: min overlap with grid-in bounds
            def score(st): return (sum(1 for p in st if 0<=p[0]<h and 0<=p[1]<w),-sum(abs(2*mr-p[0])+abs(2*mc-p[1]) for p in st),None)
            scc={}
