            cnt=sum(1 for p in st if 0<=p[0]<h and 0<=p[1]<w)
            if best is None or cnt>best[0]:
                best=(cnt,name,off_v if name=='V' else off_h)
        if best:
            cnt,name,(dr,dc)=best
            for a,b in {(2*mr-a+dr,b+dc) for a,b in S}:
